const ALLOWED_EMAILS = [
  "skunkqq@gmail.com",
  "sasadako.wu@gmail.com"
];

// AES-256-CBC 軍規加密金庫 Payload (PBKDF2 100,000 次疊代)
const ENCRYPTED_VAULT = {
  "salt": "x2nWpK5i3YfV9T+2I1BRJw==",
  "iv": "e+hpYWCIRoJogZ6WrSUPpA==",
  "ciphertext": ""
};

// 執行階段動態解密記憶體資料庫
let itineraryData = [];
let hotelsData = [];
let ticketsData = [];
let pocketPlacesData = [];

// ==========================================
// 0.1 高相容性 Base64 轉 Uint8Array 工具
// ==========================================
function base64ToUint8(base64Str) {
  const binaryString = atob(base64Str);
  const len = binaryString.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes;
}

// ==========================================
// 0.2 Web Crypto API 客戶端零知識解密引擎
// ==========================================
async function decryptVault(password) {
  try {
    if (!window.crypto || !window.crypto.subtle) {
      throw new Error("此瀏覽器環境未支援 Web Crypto API，請使用現代瀏覽器開啟。");
    }

    const salt = base64ToUint8(ENCRYPTED_VAULT.salt);
    const iv = base64ToUint8(ENCRYPTED_VAULT.iv);
    const ciphertext = base64ToUint8(ENCRYPTED_VAULT.ciphertext);

    const encoder = new TextEncoder();
    const keyMaterial = await crypto.subtle.importKey(
      "raw",
      encoder.encode(password),
      { name: "PBKDF2" },
      false,
      ["deriveKey"]
    );

    const derivedKey = await crypto.subtle.deriveKey(
      {
        name: "PBKDF2",
        salt: salt,
        iterations: 100000,
        hash: "SHA-256"
      },
      keyMaterial,
      { name: "AES-CBC", length: 256 },
      false,
      ["decrypt"]
    );

    const decryptedBuffer = await crypto.subtle.decrypt(
      { name: "AES-CBC", iv: iv },
      derivedKey,
      ciphertext
    );

    const decoder = new TextDecoder("utf-8");
    const jsonStr = decoder.decode(decryptedBuffer);
    const data = JSON.parse(jsonStr);

    return { success: true, data };
  } catch (err) {
    console.warn("AES Decryption mismatch or error:", err);
    return { success: false, error: err };
  }
}

